static async create(
  rootDir: string,
  meta: SessionMeta,
  log: WarnLog = silentLog,
  opts: SessionWriterOptions = {},
): Promise<SessionWriter> {
  const filePath = filePathFor(rootDir, meta.id);
  const srtPath = srtPathFor(rootDir, meta.id);
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(
    filePath,
    `${renderFrontmatter(meta)}\n\n## Assist\n`,
    { flag: 'wx' },
  );
  try {
    await fs.writeFile(srtPath, '', { flag: 'wx' });
  } catch (err) {
    // no orphan half-bundle: the .md went down first, so it goes too
    await fs.unlink(filePath).catch(() => {});
    throw err;
  }
  return new SessionWriter(filePath, srtPath, meta, log, opts.mergeMaxS ?? 0);
}

appendSegment(index: number, seg: Segment): Promise<void> {
  const speakerName = seg.speaker
    ? (this.meta.speakers[seg.speaker] ?? seg.speaker)
    : undefined;
  const last = this.lastSeg;
  if (
    this.mergeMaxS > 0 &&
    last !== undefined &&
    seg.speaker !== undefined &&
    seg.speaker !== '' &&
    last.speaker === seg.speaker &&
    seg.end_s - last.start_s < this.mergeMaxS
  ) {
    // Same-speaker run folding: stretch the last cue instead of appending
    // a new one. Cue numbers stay sparse (the merged cue keeps the first
    // segment's number) so cue n still maps back to socket index n-1.
    this.cueIndexFor.set(index, last.index);
    return this.enqueue(async () => {
      const srt = await fs.readFile(this.srtPath, 'utf8');
      const merged = mergeCueText(srt, seg.end_s, seg.text);
      if (merged === null) {
        this.log.warn(
          `segment ${index} not merged: last cue missing; appending instead`,
        );
        await fs.appendFile(this.srtPath, formatCue(index, seg, speakerName));
        return;
      }
      const tmp = `${this.srtPath}.tmp`;
      await fs.writeFile(tmp, merged);
      await fs.rename(tmp, this.srtPath);
    });
  }
  this.lastSeg = { index, speaker: seg.speaker, start_s: seg.start_s };
  const cue = formatCue(index, seg, speakerName);
  return this.enqueue(() => fs.appendFile(this.srtPath, cue));
}

// Translations land after newer cues may already exist, so this is a
// read -> splice -> tmp+rename cycle, serialized on the same queue as the
// appends. A missing or already-translated cue logs and skips. A segment
// folded into an earlier cue resolves to that cue and joins any existing
// translation line with a space, mirroring the source merge.
appendTranslation(index: number, text: string): Promise<void> {
  const mergedInto = this.cueIndexFor.get(index);
  return this.enqueue(async () => {
    const srt = await fs.readFile(this.srtPath, 'utf8');
    const spliced =
      mergedInto !== undefined
        ? upsertTranslationLine(srt, mergedInto + 1, text)
        : insertTranslationLine(srt, index, text);

