it('merges consecutive same-speaker segments while the span stays under the threshold', async () => {
  const w = await SessionWriter.create(
    dir,
    meta('2026-11-05-session-1000'),
    silentLog,
    { mergeMaxS: 10 },
  );
  await w.appendSegment(0, {
    text: 'Hi.',
    speaker: 'Speaker 1',
    start_s: 0,
    end_s: 2,
  });
  await w.appendSegment(1, {
    text: 'there.',
    speaker: 'Speaker 1',
    start_s: 2,
    end_s: 4.5,
  });
  await w.appendSegment(2, {
    text: 'friend.',
    speaker: 'Speaker 1',
    start_s: 4.5,
    end_s: 9,
  });
  const srt = await fs.readFile(w.srtPath, 'utf8');
  expect(srt).toBe(
    '1\n00:00:00,000 --> 00:00:09,000\nSpeaker 1: Hi. there. friend.\n\n',
  );
});

