import {
  cueCount,
  formatCue,
  formatSrtTimestamp,
  insertTranslationLine,
  mergeCueText,
  upsertTranslationLine,
} from './srt.js';

describe('mergeCueText', () => {
  it('stretches the last cue and space-joins the source text', () => {
    const srt =
      '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hi.\n\n' +
      '2\n00:00:02,000 --> 00:00:04,000\nSpeaker 2: Yo.\n\n';
    expect(mergeCueText(srt, 6.5, 'sup.')).toBe(
      '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hi.\n\n' +
        '2\n00:00:02,000 --> 00:00:06,500\nSpeaker 2: Yo. sup.\n\n',
    );
  });

  it('keeps a landed translation line below the merged source', () => {
    const srt =
      '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hi.\nXin chào.\n\n';
    expect(mergeCueText(srt, 4, 'there.')).toBe(
      '1\n00:00:00,000 --> 00:00:04,000\nSpeaker 1: Hi. there.\nXin chào.\n\n',
    );
  });

  it('returns null on an empty file', () => {
    expect(mergeCueText('', 1, 'x')).toBeNull();
  });
});

describe('upsertTranslationLine', () => {
  const srt =
    '1\n00:00:00,000 --> 00:00:02,000\nSpeaker 1: Hi. there.\n\n' +
    '2\n00:00:02,000 --> 00:00:04,000\nYo.\nDone.\n\n';

  it('pushes a first translation line', () => {
    expect(upsertTranslationLine(srt, 1, 'A.')).toContain(
      'Speaker 1: Hi. there.\nA.',
    );
  });

  it('space-joins onto an existing translation line', () => {
    expect(upsertTranslationLine(srt, 2, 'B.')).toContain('Done. B.');
  });

  it('returns null when the cue is missing', () => {
    expect(upsertTranslationLine(srt, 9, 'x')).toBeNull();
  });
});

